1	#!/usr/bin/env node
2	// Prov Guard —— 软件供应链证明与完整性校验工具（零依赖，Node >= 18）。
3	//
4	// 子命令：
5	//   keygen   --key-dir <dir> [--name <prefix>]
6	//   generate --artifact <path> --key <private-key> --out <dir> [--bundle]
7	//   policy-sign --policy <policy.json> --key <private.pem> --signature <policy.json.sig>
8	//   verify   --artifact <path> --proof <file> --signature <file> --key <public-key>
9	//            [--sbom <file> --sbom-signature <file>] [--policy <policy.json>]
10	//            [--policy-signature <policy.json.sig> --policy-key <public.pem>]
11	//   verify   --artifact <path> --bundle <proof.bundle.json> --key <public-key>
12	//            [--cosigner-key <public-key> ... --min-cosigners <n>] [--policy <policy.json>]
13	//            [--policy-signature <policy.json.sig> --policy-key <public.pem>]
14	//   gate     --artifact <path> --attestation <gate.attestation.json>
15	//            --sbom <gate.sbom.json> --policy <gate.policy.json>
16	//
17	// gate 为独立发布门禁：只接受本地公开文件（不读取密钥或凭证；验签公钥内嵌于
18	// 证明），不改动其他子命令的文件格式、标准输出、退出码与异常处理。
19	// gate 全部错误在 stderr 输出错误码：InputError（退出 2）/ PolicyError（退出 2）/
20	// VerificationError（退出 3）；策略拒绝为正常 denied 报告（退出 4），全部通过为
21	// allowed 报告（退出 0）。
22	//
23	// 所有输出均为 UTF-8；成功结果写 stdout，错误结果写 stderr。
24	
25	import {
26	  createHash,
27	  createPrivateKey,
28	  createPublicKey,
29	  generateKeyPairSync,
30	  sign as cryptoSign,
31	  verify as cryptoVerify,
32	} from 'node:crypto';
33	import { constants as fsConstants, readFileSync, realpathSync } from 'node:fs';
34	import { access, mkdir, readdir, readFile, realpath, rename, rm, stat, writeFile } from 'node:fs/promises';
35	import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
36	import { fileURLToPath } from 'node:url';
37	
38	export const PROOF_VERSION = '1.0';
39	// 启用多方共签时证明版本升为 1.1；共签清单（proof/sbom.cosignatures.json）的 schemaVersion。
40	export const PROOF_VERSION_COSIGN = '1.1';
41	export const COSIGN_SCHEMA_VERSION = '1.0';
42	// 证明分发包（proof.bundle.json）版本与成员逻辑名。
43	export const BUNDLE_VERSION = '1.0';
44	export const BUNDLE_BASE_MEMBERS = Object.freeze(['proof', 'proof-signature', 'sbom', 'sbom-signature']);
45	export const BUNDLE_COSIGN_MEMBERS = Object.freeze(['proof-cosignatures', 'sbom-cosignatures']);
46	
47	// ---------------------------------------------------------------------------
48	// 错误类型：携带机器可读错误码，CLI 边界统一转换为非零退出。
49	// ---------------------------------------------------------------------------
50	
51	export const ERROR_CODES = Object.freeze({
52	  INPUT_NOT_FOUND: 'INPUT_NOT_FOUND',
53	  PERMISSION_DENIED: 'PERMISSION_DENIED',
54	  PROOF_INVALID: 'PROOF_INVALID',
55	  SIGNATURE_INVALID: 'SIGNATURE_INVALID',
56	  KEY_NOT_FOUND: 'KEY_NOT_FOUND',
57	  INTEGRITY_MISMATCH: 'INTEGRITY_MISMATCH',
58	  POLICY_INVALID: 'POLICY_INVALID',
59	  POLICY_VIOLATION: 'POLICY_VIOLATION',
60	  SYMLINK_INVALID: 'SYMLINK_INVALID',
61	  USAGE_ERROR: 'USAGE_ERROR',
62	});
63	
64	class ProvError extends Error {
65	  constructor(code, message, details) {
66	    super(message);
67	    this.name = 'ProvError';
68	    this.code = code;
69	    if (details !== undefined) this.details = details;
70	  }
71	}
72	
73	// 把 Node 底层错误归类为 INPUT_NOT_FOUND / PERMISSION_DENIED，其余原样抛出。
74	function wrapFsError(err, context) {
75	  if (err instanceof ProvError) return err;
76	  const where = context ? `${context}: ` : '';
77	  if (err && err.code === 'ENOENT') {
78	    return new ProvError(ERROR_CODES.INPUT_NOT_FOUND, `${where}路径不存在 (${err.path || 'unknown path'})`);
79	  }
80	  if (err && (err.code === 'EACCES' || err.code === 'EPERM')) {
81	    return new ProvError(ERROR_CODES.PERMISSION_DENIED, `${where}权限不足 (${err.path || 'unknown path'})`);
82	  }
83	  return err;
84	}
85	
86	// ---------------------------------------------------------------------------
87	// 路径与摘要工具
88	// ---------------------------------------------------------------------------
89	
90	// 清单中的相对路径统一使用正斜杠，保证跨平台稳定。
91	export function toPosix(relPath) {
92	  return relPath.split(sep).join('/');
93	}
94	
95	// 稳定哈希：SHA-256，摘要对象按 key 排序后以 UTF-8 序列化（两空格缩进）。
96	export function stableJsonStringify(value) {
97	  return JSON.stringify(sortDeep(value), null, 2);
98	}
99	
100	function sortDeep(value) {
101	  if (Array.isArray(value)) return value.map(sortDeep);
102	  if (value !== null && typeof value === 'object') {
103	    const out = {};
104	    for (const key of Object.keys(value).sort()) out[key] = sortDeep(value[key]);
105	    return out;
106	  }
107	  return value;
108	}
109	
110	export function sha256Hex(data) {
111	  return createHash('sha256').update(data).digest('hex');
112	}
113	
114	// 公钥指纹：对 SPKI 编码的 DER 字节取 SHA-256。写入证明并随证明一起签名，
115	// 验证时据此区分“使用了错误公钥”（指纹不一致）与“签名内容被篡改”（指纹一致但验签失败）。
116	export function keyFingerprint(keyObj) {
117	  return sha256Hex(keyObj.export({ type: 'spki', format: 'der' }));
118	}
119	
120	// ---------------------------------------------------------------------------
121	// 产物扫描：递归列出全部常规文件（含符号链接解引用后的目标），
122	// 空目录自然产生空清单；零字节文件按真实文件记录。
123	// 符号链接安全规则（按真实路径判定）：
124	//   - 目标越出产物根目录                 -> SYMLINK_INVALID / outside-root；
125	//   - 目标为当前递归祖先链上的目录（含根目录自身），或链接互相成环（ELOOP）
126	//                                        -> SYMLINK_INVALID / cycle；
127	//   - 指向根目录内部普通文件/目录的链接按链接路径记录目标内容；
128	//     祖先链之外的重复目标允许展开（有向无环，不会形成回路）。
129	// 判定在读取目标内容之前完成，危险链接不会被解引用读取。
130	// ---------------------------------------------------------------------------
131	
132	// 符号链接安全检查失败：携带相对路径与原因（cycle / outside-root）。
133	function symlinkError(fullPath, rootDir, reason) {
134	  const relPath = toPosix(relative(rootDir, fullPath));
135	  const message =
136	    reason === 'cycle'
137	      ? `符号链接形成回路: ${relPath}`
138	      : `符号链接越出产物根目录: ${relPath}`;
139	  return new ProvError(ERROR_CODES.SYMLINK_INVALID, message, { path: relPath, reason });
140	}
141	
142	// 解析真实路径；底层错误按既有归类转换。
143	async function realPathOf(p, context) {
144	  try {
145	    return await realpath(p);
146	  } catch (err) {
147	    throw wrapFsError(err, context);
148	  }
149	}
150	
151	async function walkFiles(rootDir) {
152	  const found = [];
153	  const rootReal = await realPathOf(rootDir, '读取产物目录');
154	  // chain 为当前递归路径上各级目录的真实路径，用于识别指回祖先的链接回路。
155	  async function walk(dir, chain) {
156	    let entries;
157	    try {
158	      entries = await readdir(dir, { withFileTypes: true });
159	    } catch (err) {
160	      throw wrapFsError(err, '读取产物目录');
161	    }
162	    for (const entry of entries) {
163	      const full = join(dir, entry.name);
164	      if (entry.isDirectory()) {
165	        await walk(full, [...chain, await realPathOf(full, '读取产物目录')]);
166	      } else if (entry.isFile()) {
167	        found.push(full);
168	      } else if (entry.isSymbolicLink()) {
169	        // 先解析真实目标并做安全判定，再按目标类型处理：
170	        // 指向目录则继续递归，指向文件则按链接路径记录。
171	        let targetReal;
172	        try {
173	          targetReal = await realpath(full);
174	        } catch (err) {
175	          // 链接互相指向成环（如 a -> b、b -> a）时 realpath 报 ELOOP。
176	          if (err && err.code === 'ELOOP') throw symlinkError(full, rootDir, 'cycle');
177	          throw wrapFsError(err, '读取符号链接');
178	        }
179	        if (!isWithin(targetReal, rootReal)) {
180	          throw symlinkError(full, rootDir, 'outside-root');
181	        }
182	        if (chain.includes(targetReal)) {
183	          throw symlinkError(full, rootDir, 'cycle');
184	        }
185	        let target;
186	        try {
187	          target = await stat(full);
188	        } catch (err) {
189	          throw wrapFsError(err, '读取符号链接');
190	        }
191	        if (target.isDirectory()) await walk(full, [...chain, targetReal]);
192	        else if (target.isFile()) found.push(full);
193	      }
194	      // 其他特殊文件（套接字/设备等）忽略。
195	    }
196	  }
197	  await walk(rootDir, [rootReal]);
198	  return found;
199	}
200	
201	// 判断 root 是否位于 outDir 之内（用于从扫描结果排除输出目录自身）。
202	function isWithin(pathAbs, dirAbs) {
203	  const relPath = relative(dirAbs, pathAbs);
204	  return relPath === '' || (!!relPath && !relPath.startsWith('..') && !isAbsolute(relPath));
205	}
206	
207	async function fileTypeFromPath(fullPath, data) {
208	  // 极简魔数嗅探，仅用于清单的 type 字段；不识别时回退为扩展名或 "data"。
209	  // 一律使用字节数组，避免多字节字符串经 UTF-8 编码后长度/取值不符。
210	  const startsWith = (bytes) =>
211	    data.length >= bytes.length && bytes.every((b, i) => data[i] === b);
212	  if (startsWith([0x1f, 0x8b])) return 'application/gzip';
213	  if (startsWith([0x50, 0x4b, 0x03, 0x04])) return 'application/zip';
214	  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'application/pdf'; // %PDF-
215	  if (startsWith([0x7f, 0x45, 0x4c, 0x46])) return 'application/x-elf';
216	  if (startsWith([0x4d, 0x5a])) return 'application/x-dosexec'; // MZ
217	  if (startsWith([0xff, 0xd8, 0xff])) return 'image/jpeg';
218	  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
219	  // 类脚本/文本：UTF BOM，或前 512 字节不含 NUL 则视为 text。
220	  if (
221	    startsWith([0xef, 0xbb, 0xbf]) ||
222	    startsWith([0xff, 0xfe]) ||
223	    startsWith([0xfe, 0xff])
224	  ) {
225	    return 'text/plain';
226	  }
227	  if (!data.subarray(0, 512).includes(0)) return 'text/plain';
228	  const ext = basename(fullPath).split('.').pop();
229	  return ext && ext !== basename(fullPath) ? `application/x-${ext.toLowerCase()}` : 'application/octet-stream';
230	}
231	
232	// 构建 SBOM。时间字段不进入清单，文件摘要只依赖文件字节与相对路径。
233	// excludeDir 为输出目录的绝对路径（若位于产物内部则排除）。
234	export async function buildSbom(artifactPath, excludeDir) {
235	  const artifactAbs = resolve(artifactPath);
236	  let artifactStat;
237	  try {
238	    artifactStat = await stat(artifactAbs);
239	  } catch (err) {
240	    throw wrapFsError(err, '读取产物');
241	  }
242	
243	  const rootDir = artifactStat.isDirectory() ? artifactAbs : dirname(artifactAbs);
244	  const excludeAbs = excludeDir ? resolve(excludeDir) : null;
245	
246	  let files;
247	  if (artifactStat.isDirectory()) {
248	    files = await walkFiles(artifactAbs);
249	  } else {
250	    files = [artifactAbs];
251	  }
252	
253	  const entries = [];
254	  for (const full of files) {
255	    if (excludeAbs && isWithin(full, excludeAbs)) continue;
256	    let data;
257	    try {
258	      data = await readFile(full);
259	    } catch (err) {
260	      throw wrapFsError(err, '读取产物文件');
261	    }
262	    const relPath = toPosix(relative(rootDir, full));
263	    entries.push({
264	      path: relPath,
265	      sha256: sha256Hex(data),
266	      size: data.length,
267	      type: await fileTypeFromPath(full, data),
268	    });
269	  }
270	
271	  // 按相对路径排序，保证同一输入产生字节级一致的清单。
272	  entries.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
273	
274	  return {
275	    schemaVersion: '1.0',
276	    artifactName: artifactStat.isDirectory() ? basename(artifactAbs) : basename(artifactAbs),
277	    rootType: artifactStat.isDirectory() ? 'directory' : 'file',
278	    files: entries,
279	  };
280	}
281	
282	// 顶层产物摘要：对“排序后的文件条目列表”做稳定哈希。
283	// 任何字节变化、文件新增/删除/重命名都会改变该摘要。
284	export function computeArtifactDigest(sbom) {
285	  return sha256Hex(stableJsonStringify(sbom.files));
286	}
287	
288	// ---------------------------------------------------------------------------
289	// 密钥与签名（Ed25519，PEM）
290	// ---------------------------------------------------------------------------
291	
292	function readPrivateKey(keyPath) {
293	  let pem;
294	  try {
295	    pem = readFileSync(keyPath);
296	  } catch (err) {
297	    throw wrapFsError(err, '读取私钥');
298	  }
299	  let keyObj;
300	  try {
301	    keyObj = createPrivateKey({ key: pem, format: 'pem' });
302	  } catch {
303	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `私钥无法解析或格式不受支持: ${keyPath}`);
304	  }
305	  if (keyObj.asymmetricKeyType !== 'ed25519') {
306	    throw new ProvError(
307	      ERROR_CODES.KEY_NOT_FOUND,
308	      `私钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
309	    );
310	  }
311	  return keyObj;
312	}
313	
314	function readPublicKey(keyPath) {
315	  let pem;
316	  try {
317	    pem = readFileSync(keyPath);
318	  } catch (err) {
319	    throw wrapFsError(err, '读取公钥');
320	  }
321	  let keyObj;
322	  try {
323	    keyObj = createPublicKey({ key: pem, format: 'pem' });
324	  } catch {
325	    throw new ProvError(ERROR_CODES.KEY_NOT_FOUND, `公钥无法解析或格式不受支持: ${keyPath}`);
326	  }
327	  if (keyObj.asymmetricKeyType !== 'ed25519') {
328	    throw new ProvError(
329	      ERROR_CODES.KEY_NOT_FOUND,
330	      `公钥类型不是 Ed25519（实际为 ${keyObj.asymmetricKeyType}）: ${keyPath}`,
331	    );
332	  }
333	  return keyObj;
334	}
335	
336	// 生成阶段时间戳采用 UTC ISO-8601；它只写入 proof，不参与任何摘要。
337	function nowIso() {
338	  return new Date().toISOString();
339	}
340	
341	// ---------------------------------------------------------------------------
342	// keygen
343	// ---------------------------------------------------------------------------
344	
345	export async function keygen({ keyDir, name = 'provguard' }) {
346	  const absDir = resolve(keyDir);
347	  try {
348	    await mkdir(absDir, { recursive: true });
349	  } catch (err) {
350	    throw wrapFsError(err, '创建密钥目录');
351	  }
352	  const { publicKey, privateKey } = generateKeyPairSync('ed25519');
353	  const privPath = join(absDir, `${name}.private.pem`);
354	  const pubPath = join(absDir, `${name}.public.pem`);
355	  try {
356	    await writeFile(
357	      privPath,
358	      privateKey.export({ type: 'pkcs8', format: 'pem' }),
359	      { mode: 0o600 },
360	    );
361	    await writeFile(
362	      pubPath,
363	      publicKey.export({ type: 'spki', format: 'pem' }),
364	      { mode: 0o644 },
365	    );
366	  } catch (err) {
367	    throw wrapFsError(err, '写入密钥');
368	  }
369	  return { privateKeyPath: privPath, publicKeyPath: pubPath };
370	}
371	
372	// ---------------------------------------------------------------------------
373	// generate
374	// ---------------------------------------------------------------------------
375	
376	export async function generate({ artifact, key, out, coKeys = [], bundle = false }) {
377	  // 输入检查：产物与私钥必须存在且可读。
378	  const artifactAbs = resolve(artifact);
379	  const keyAbs = resolve(key);
380	  const coSign = coKeys.length > 0;
381	  const coKeyAbsList = coKeys.map((p) => resolve(p));
382	  const inputs = [
383	    [artifactAbs, '产物'],
384	    [keyAbs, '私钥'],
385	  ];
386	  for (const p of coKeyAbsList) inputs.push([p, '共签私钥']);
387	  for (const [p, label] of inputs) {
388	    try {
389	      await access(p, fsConstants.R_OK);
390	    } catch (err) {
391	      throw wrapFsError(err, `读取${label}`);
392	    }
393	  }
394	
395	  const outAbs = resolve(out);
396	  const parent = dirname(outAbs);
397	  try {
398	    await mkdir(parent, { recursive: true });
399	  } catch (err) {
400	    throw wrapFsError(err, '创建输出目录');
401	  }
402	
403	  // 若输出目录尚不存在，先按真实路径创建，再据此排除。
404	  try {
405	    await mkdir(outAbs, { recursive: true });
406	  } catch (err) {
407	    throw wrapFsError(err, '创建输出目录');
408	  }
409	  let outReal;
410	  try {
411	    outReal = await realpath(outAbs);
412	  } catch (err) {
413	    throw wrapFsError(err, '解析输出目录');
414	  }
415	
416	  const privateKey = readPrivateKey(keyAbs);
417	  // 由私钥导出对应公钥，记录其指纹到证明中，供验证区分错误公钥与签名失配。
418	  const signingPublicKey = createPublicKey(privateKey);
419	  const signerKeyFingerprint = keyFingerprint(signingPublicKey);
420	
421	  // 共签私钥：逐一读取并校验为 Ed25519；指纹不得重复，也不得与主签名密钥相同，
422	  // 否则为 USAGE_ERROR。共签者按指纹升序排列，保证输出确定。
423	  const coSigners = [];
424	  if (coSign) {
425	    const seen = new Set([signerKeyFingerprint.toLowerCase()]);
426	    for (const p of coKeyAbsList) {
427	      const coKey = readPrivateKey(p);
428	      const fingerprint = keyFingerprint(createPublicKey(coKey));
429	      if (seen.has(fingerprint.toLowerCase())) {
430	        throw new ProvError(
431	          ERROR_CODES.USAGE_ERROR,
432	          '共签私钥重复或与主密钥相同（--co-key 必须互不相同且不同于 --key）',
433	        );
434	      }
435	      seen.add(fingerprint.toLowerCase());
436	      coSigners.push({ key: coKey, fingerprint });
437	    }
438	    coSigners.sort((a, b) => (a.fingerprint < b.fingerprint ? -1 : a.fingerprint > b.fingerprint ? 1 : 0));
439	  }
440	
441	  const sbom = await buildSbom(artifactAbs, outReal);
442	  const artifactDigest = computeArtifactDigest(sbom);
443	
444	  // SBOM 规范字节：稳定 JSON（去尾换行后的 UTF-8）。proof 中的 sbomDigest 与
445	  // sbom.json.sig 绑定同一组字节，防止证明有效而 sbom.json 被整体替换。
446	  const sbomCanonical = stableJsonStringify(sbom);
447	  const sbomDigest = sha256Hex(sbomCanonical);
448	
449	  const proof = {
450	    proofVersion: coSign ? PROOF_VERSION_COSIGN : PROOF_VERSION,
451	    artifactName: basename(artifactAbs),
452	    artifactDigest,
453	    fileName: basename(artifactAbs),
454	    size: sbom.files.reduce((n, f) => n + f.size, 0),
455	    generatedAt: nowIso(),
456	    signerKeyFingerprint,
457	    sbomDigest,
458	    files: sbom.files,
459	  };
460	  // 启用共签时证明声明共签者集合（按指纹升序、已去重），随证明一起被主签名保护。
461	  if (coSign) {
462	    proof.cosignerKeyFingerprints = coSigners.map((c) => c.fingerprint);
463	  }
464	  // 稳定字段顺序：proof 先按既定顺序构造，再整体排序输出。
465	  const proofJson = stableJsonStringify(proof) + '\n';
466	  const sbomJson = sbomCanonical + '\n';
467	
468	  // 对证明的规范字节（不含尾部换行）签名，验证时使用同一规范形式。
469	  // Ed25519 为纯签名算法，不接受摘要算法参数，故用 sign(null, data, key)。
470	  const signature = cryptoSign(null, Buffer.from(proofJson.trimEnd(), 'utf8'), privateKey);
471	  const signatureB64 = signature.toString('base64') + '\n';
472	  // 对 SBOM 规范字节单独签名，Base64 加换行保存。
473	  const sbomSignature = cryptoSign(null, Buffer.from(sbomCanonical, 'utf8'), privateKey);
474	  const sbomSignatureB64 = sbomSignature.toString('base64') + '\n';
475	
476	  const proofPath = join(outReal, 'proof.json');
477	  const sbomPath = join(outReal, 'sbom.json');
478	  const sigPath = join(outReal, 'proof.json.sig');
479	  const sbomSigPath = join(outReal, 'sbom.json.sig');
480	  // 共签清单：每个共签者对与主签名相同的证明规范字节签名（proof.cosignatures.json），
481	  // 并另对 SBOM 规范字节签名（sbom.cosignatures.json）。不提供 --co-key 时不创建这些文件。
482	  const proofCosigPath = coSign ? join(outReal, 'proof.cosignatures.json') : null;
483	  const sbomCosigPath = coSign ? join(outReal, 'sbom.cosignatures.json') : null;
484	  // 证明分发包：--bundle 时在输出目录额外写出 proof.bundle.json（不影响既有文件）。
485	  const bundlePath = bundle ? join(outReal, 'proof.bundle.json') : null;
486	  try {
487	    await atomicWrite(proofPath, proofJson);
488	    await atomicWrite(sbomPath, sbomJson);
489	    await atomicWrite(sigPath, signatureB64);
490	    await atomicWrite(sbomSigPath, sbomSignatureB64);
491	    let proofCosigJson = null;
492	    let sbomCosigJson = null;
493	    if (coSign) {
494	      const proofBytes = Buffer.from(proofJson.trimEnd(), 'utf8');
495	      const sbomBytes = Buffer.from(sbomCanonical, 'utf8');
496	      const cosignManifest = (bytes) => ({
497	        schemaVersion: COSIGN_SCHEMA_VERSION,
498	        artifactDigest,
499	        sbomDigest,
500	        signers: coSigners.map((c) => ({
501	          keyFingerprint: c.fingerprint,
502	          signature: cryptoSign(null, bytes, c.key).toString('base64'),
503	        })),
504	      });
505	      proofCosigJson = stableJsonStringify(cosignManifest(proofBytes)) + '\n';
506	      sbomCosigJson = stableJsonStringify(cosignManifest(sbomBytes)) + '\n';
507	      await atomicWrite(proofCosigPath, proofCosigJson);
508	      await atomicWrite(sbomCosigPath, sbomCosigJson);
509	    }
510	    if (bundle) {
511	      const entries = [
512	        ['proof', proofJson],
513	        ['proof-signature', signatureB64],
514	        ['sbom', sbomJson],
515	        ['sbom-signature', sbomSignatureB64],
516	      ];
517	      if (coSign) {
518	        entries.push(['proof-cosignatures', proofCosigJson], ['sbom-cosignatures', sbomCosigJson]);
519	      }
520	      await atomicWrite(bundlePath, buildBundleJson(entries));
521	    }
522	  } catch (err) {
523	    throw wrapFsError(err, '写入证明产物');
524	  }
525	
526	  const result = {
527	    proofPath,
528	    sbomPath,
529	    signaturePath: sigPath,
530	    sbomSignaturePath: sbomSigPath,
531	    artifactDigest,
532	    sbomDigest,
533	    fileCount: sbom.files.length,
534	    proofVersion: proof.proofVersion,
535	  };
536	  if (coSign) {
537	    result.cosignerCount = coSigners.length;
538	    result.proofCosignaturesPath = proofCosigPath;
539	    result.sbomCosignaturesPath = sbomCosigPath;
540	  }
541	  if (bundle) {
542	    result.bundlePath = bundlePath;
543	  }
544	  return result;
545	}
