547	// ---------------------------------------------------------------------------
548	// policy-sign：为既有策略文件生成独立的 Ed25519 签名。
549	// 不改写策略、私钥或任何证明产物；签名覆盖 policy.json 的 UTF-8 稳定 JSON
550	// 字节（键名排序、两空格缩进、末尾换行），Base64 加换行保存，重复生成逐字节一致。
551	// 校验顺序：策略与私钥可读 -> 策略 JSON 合法（POLICY_INVALID）-> 私钥可解析且为
552	// Ed25519（KEY_NOT_FOUND）-> 写签名（写失败 PERMISSION_DENIED）。
553	// ---------------------------------------------------------------------------
554	
555	export async function policySign({ policy: policyPath, key: keyPath, signature: sigPath }) {
556	  const policyAbs = resolve(policyPath);
557	  const keyAbs = resolve(keyPath);
558	  const sigAbs = resolve(sigPath);
559	  // 输入检查：策略与私钥必须存在且可读。
560	  for (const [p, label] of [
561	    [policyAbs, '策略文件'],
562	    [keyAbs, '私钥'],
563	  ]) {
564	    try {
565	      await access(p, fsConstants.R_OK);
566	    } catch (err) {
567	      throw wrapFsError(err, `读取${label}`);
568	    }
569	  }
570	
571	  // 以磁盘字节为真解析并校验策略结构，再重算稳定 JSON 字节作为签名输入。
572	  let policyText;
573	  try {
574	    policyText = await readFileUtf8(policyAbs);
575	  } catch (err) {
576	    throw wrapFsError(err, '读取策略文件');
577	  }
578	  let policy;
579	  try {
580	    policy = JSON.parse(policyText);
581	  } catch {
582	    throw new ProvError(ERROR_CODES.POLICY_INVALID, '策略文件不是合法的 JSON');
583	  }
584	  // 复用既有严格校验：未知字段、取值与 policyVersion 非法均为 POLICY_INVALID。
585	  const policyError = validatePolicyObject(policy);
586	  if (policyError) {
587	    throw new ProvError(ERROR_CODES.POLICY_INVALID, policyError);
588	  }
589	
590	  const privateKey = readPrivateKey(keyAbs);
591	  const signerFingerprint = keyFingerprint(createPublicKey(privateKey));
592	
593	  const canonicalBytes = Buffer.from(stableJsonStringify(policy) + '\n', 'utf8');
594	  const signatureB64 = cryptoSign(null, canonicalBytes, privateKey).toString('base64') + '\n';
595	  try {
596	    await atomicWrite(sigAbs, signatureB64);
597	  } catch (err) {
598	    throw wrapFsError(err, '写入策略签名文件');
599	  }
600	
601	  return {
602	    policyPath: policyAbs,
603	    signaturePath: sigAbs,
604	    policySignerFingerprint: signerFingerprint,
605	  };
606	}
607	
608	// ---------------------------------------------------------------------------
609	// 证明分发包（proof.bundle.json）：把一套证明产物打包为单个稳定 JSON 文件。
610	// members 按逻辑名排序（stableJsonStringify 按键名排序），每项保存原文件字节的
611	// Base64、SHA-256 与字节长度；原样保留文件字节（含签名输入的规范字节），
612	// 因此除 generatedAt、proof 及其签名外，重复生成的包内容逐字节稳定。
613	// ---------------------------------------------------------------------------
614	
615	function bundleMember(content) {
616	  const buf = Buffer.isBuffer(content) ? content : Buffer.from(content, 'utf8');
617	  return { data: buf.toString('base64'), sha256: sha256Hex(buf), size: buf.length };
618	}
619	
620	function buildBundleJson(entries) {
621	  const members = {};
622	  for (const [name, content] of entries) members[name] = bundleMember(content);
623	  return stableJsonStringify({ bundleVersion: BUNDLE_VERSION, members }) + '\n';
624	}
625	
626	// 解析并校验分发包结构，返回 { members: Map<逻辑名, Buffer>, hasCosignMembers }。
627	// JSON 不可解析、bundleVersion 非 1.0、成员缺失或多余、Base64 非法、
628	// 长度或 SHA-256 不符均为 PROOF_INVALID。
629	function parseBundle(text) {
630	  let bundle;
631	  try {
632	    bundle = JSON.parse(text);
633	  } catch {
634	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明分发包不是合法的 JSON');
635	  }
636	  if (bundle === null || typeof bundle !== 'object' || Array.isArray(bundle)) {
637	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明分发包顶层必须是 JSON 对象');
638	  }
639	  if (bundle.bundleVersion !== BUNDLE_VERSION) {
640	    throw new ProvError(
641	      ERROR_CODES.PROOF_INVALID,
642	      `分发包 bundleVersion 缺失或不受支持（应为 ${BUNDLE_VERSION}）`,
643	    );
644	  }
645	  const rawMembers = bundle.members;
646	  if (rawMembers === null || typeof rawMembers !== 'object' || Array.isArray(rawMembers)) {
647	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '分发包字段缺失或类型非法: members');
648	  }
649	  const known = new Set([...BUNDLE_BASE_MEMBERS, ...BUNDLE_COSIGN_MEMBERS]);
650	  for (const name of Object.keys(rawMembers)) {
651	    if (!known.has(name)) {
652	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `分发包含有多余成员: ${name}`);
653	    }
654	  }
655	  for (const name of BUNDLE_BASE_MEMBERS) {
656	    if (!(name in rawMembers)) {
657	      throw new ProvError(ERROR_CODES.PROOF_INVALID, `分发包缺少成员: ${name}`);
658	    }
659	  }
660	  // 共签成员必须成对出现（与生成时的输出一致）。
661	  const hasProofCosig = BUNDLE_COSIGN_MEMBERS[0] in rawMembers;
662	  const hasSbomCosig = BUNDLE_COSIGN_MEMBERS[1] in rawMembers;
663	  if (hasProofCosig !== hasSbomCosig) {
664	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '分发包共签成员必须成对出现');
665	  }
666	  const members = new Map();
667	  for (const [name, m] of Object.entries(rawMembers)) {
668	    members.set(name, decodeBundleMember(name, m));
669	  }
670	  return { members, hasCosignMembers: hasProofCosig };
671	}
672	
673	function decodeBundleMember(name, member) {
674	  const bad = (why) => new ProvError(ERROR_CODES.PROOF_INVALID, `分发包成员 ${name} ${why}`);
675	  if (member === null || typeof member !== 'object' || Array.isArray(member)) {
676	    throw bad('必须是对象');
677	  }
678	  if (typeof member.data !== 'string' || !/^[A-Za-z0-9+/]*={0,2}$/.test(member.data)) {
679	    throw bad('的 data 不是合法的 Base64 内容');
680	  }
681	  if (typeof member.sha256 !== 'string' || !/^[0-9a-f]{64}$/i.test(member.sha256)) {
682	    throw bad('的 sha256 不是合法的 SHA-256 十六进制摘要');
683	  }
684	  if (!isNonNegSafeInt(member.size)) {
685	    throw bad('的 size 非法（应为非负安全整数）');
686	  }
687	  const buf = Buffer.from(member.data, 'base64');
688	  if (buf.length !== member.size) {
689	    throw bad('的字节长度与 size 不符');
690	  }
691	  if (sha256Hex(buf).toLowerCase() !== member.sha256.toLowerCase()) {
692	    throw bad('的 SHA-256 与内容不符');
693	  }
694	  return buf;
695	}
696	
697	// 同目录临时文件 + rename，避免半成品证明文件留在输出目录。
698	async function atomicWrite(target, contents) {
699	  const dir = dirname(target);
700	  const tmp = join(dir, `.${basename(target)}.${process.pid}.tmp`);
701	  await writeFile(tmp, contents, { mode: 0o644 });
702	  try {
703	    await rename(tmp, target);
704	  } catch (err) {
705	    await rm(tmp, { force: true });
706	    throw err;
707	  }
708	}
709	
710	// ---------------------------------------------------------------------------
711	// verify
712	// ---------------------------------------------------------------------------
713	
714	export async function verify({
715	  artifact,
716	  proof: proofPath,
717	  signature: sigPath,
718	  key: pubKeyPath,
719	  sbom: sbomPath,
720	  sbomSignature: sbomSigPath,
721	  policy: policyPath,
722	  policySignature: policySigPath,
723	  policyKey: policyKeyPath,
724	  cosignatures: cosigDir,
725	  cosignerKeys,
726	  minCosigners,
727	  bundle: bundlePath,
728	}) {
729	  const bundleMode = bundlePath !== undefined;
730	  const artifactAbs = resolve(artifact);
731	  const keyAbs = resolve(pubKeyPath);
732	  const bundleAbs = bundleMode ? resolve(bundlePath) : null;
733	  const proofAbs = bundleMode ? null : resolve(proofPath);
734	  const sigAbs = bundleMode ? null : resolve(sigPath);
735	
736	  // --sbom 与 --sbom-signature 必须成对出现；只给一者是用法错误。
737	  // 包模式自带 SBOM 与其签名成员，视为始终启用 SBOM 校验。
738	  let sbomMode = true;
739	  let sbomAbs = null;
740	  let sbomSigAbs = null;
741	  if (!bundleMode) {
742	    sbomMode = sbomPath !== undefined || sbomSigPath !== undefined;
743	    if (sbomMode && (sbomPath === undefined || sbomSigPath === undefined)) {
744	      throw new ProvError(ERROR_CODES.USAGE_ERROR, '--sbom 与 --sbom-signature 必须成对提供');
745	    }
746	    sbomAbs = sbomMode ? resolve(sbomPath) : null;
747	    sbomSigAbs = sbomMode ? resolve(sbomSigPath) : null;
748	  }
749	
750	  // 共签校验参数必须成套：独立文件模式为 --cosignatures、--cosigner-key（可重复）、
751	  // --min-cosigners 三者；包模式清单位于包内，只需后两者。
752	  const cosignMode =
753	    cosigDir !== undefined || cosignerKeys !== undefined || minCosigners !== undefined;
754	  if (cosignMode) {
755	    const pairOk = cosignerKeys !== undefined && minCosigners !== undefined;
756	    const sourceOk = bundleMode || cosigDir !== undefined;
757	    if (!pairOk || !sourceOk) {
758	      throw new ProvError(
759	        ERROR_CODES.USAGE_ERROR,
760	        bundleMode
761	          ? '--cosigner-key 与 --min-cosigners 必须同时提供'
762	          : '--cosignatures、--cosigner-key 与 --min-cosigners 必须同时提供',
763	      );
764	    }
765	  }
766	  const cosignerKeyList = cosignMode
767	    ? (Array.isArray(cosignerKeys) ? cosignerKeys : [cosignerKeys])
768	    : [];
769	
770	  // 策略签名：--policy-signature 与 --policy-key 必须同时给且必须与 --policy 同时给
771	  // （缺一/无 --policy 由 CLI 层判为 USAGE_ERROR；库入口同样拒绝不完整参数）。
772	  const policySignMode = policySigPath !== undefined || policyKeyPath !== undefined;
773	  if (policySignMode && (policySigPath === undefined || policyKeyPath === undefined || policyPath === undefined)) {
774	    throw new ProvError(
775	      ERROR_CODES.USAGE_ERROR,
776	      '--policy-signature 与 --policy-key 必须与 --policy 同时提供',
777	    );
778	  }
779	  const policySigAbs = policySignMode ? resolve(policySigPath) : null;
780	  const policyKeyAbs = policySignMode ? resolve(policyKeyPath) : null;
781	
782	  // 1) 所有输入必须存在且可读。
783	  const inputs = [[artifactAbs, '产物']];
784	  if (bundleMode) {
785	    inputs.push([bundleAbs, '证明分发包']);
786	  } else {
787	    inputs.push([proofAbs, '证明文件'], [sigAbs, '签名文件']);
788	  }
789	  inputs.push([keyAbs, '公钥']);
790	  if (!bundleMode && sbomMode) {
791	    inputs.push([sbomAbs, 'SBOM 文件'], [sbomSigAbs, 'SBOM 签名文件']);
792	  }
793	  // 策略、策略签名与策略公钥在最后的策略阶段才读取（与既有“篡改优先于策略”一致），
794	  // 不加入此处的早期输入检查。
795	  for (const [p, label] of inputs) {
796	    try {
797	      await access(p, fsConstants.R_OK);
798	    } catch (err) {
799	      throw wrapFsError(err, `读取${label}`);
800	    }
801	  }
802	
803	  // 2) 公钥必须可解析且为 Ed25519 —— 错误/不支持的公钥归 KEY_NOT_FOUND。
804	  const publicKey = readPublicKey(keyAbs);
805	
806	  // 3) 证明来源：包模式先解析并校验分发包结构，再取出各成员原始字节；
807	  //    独立文件模式直接读取对应文件。
808	  let bundleMembers = null;
809	  let hasCosignMembers = false;
810	  let proofText;
811	  let sigText;
812	  let sbomText = null;
813	  let sbomSigText = null;
814	  if (bundleMode) {
815	    const bundleText = await readFileUtf8(bundleAbs);
816	    const parsed = parseBundle(bundleText);
817	    bundleMembers = parsed.members;
818	    hasCosignMembers = parsed.hasCosignMembers;
819	    proofText = bundleMembers.get('proof').toString('utf8');
820	    sigText = bundleMembers.get('proof-signature').toString('utf8');
821	    sbomText = bundleMembers.get('sbom').toString('utf8');
822	    sbomSigText = bundleMembers.get('sbom-signature').toString('utf8');
823	  } else {
824	    try {
825	      proofText = await readFileUtf8(proofAbs);
826	    } catch (err) {
827	      throw wrapFsError(err, '读取证明文件');
828	    }
829	  }
830	  // 证明文件必须是可解析的 JSON 且结构合法 —— 否则 PROOF_INVALID。
831	  let proof;
832	  try {
833	    proof = JSON.parse(proofText);
834	  } catch {
835	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明文件不是合法的 JSON');
836	  }
837	  const proofError = validateProof(proof);
838	  if (proofError) {
839	    throw new ProvError(ERROR_CODES.PROOF_INVALID, proofError);
840	  }
841	
842	  // 包模式：共签成员与证明声明必须一致 —— 声明了共签者而缺少共签成员，
843	  // 或未声明却携带共签成员，均为成员缺失/多余（PROOF_INVALID）。
844	  if (bundleMode) {
845	    const declared = proof.cosignerKeyFingerprints !== undefined;
846	    if (declared && !hasCosignMembers) {
847	      throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明声明了共签者，但分发包缺少共签成员');
848	    }
849	    if (!declared && hasCosignMembers) {
850	      throw new ProvError(ERROR_CODES.PROOF_INVALID, '证明未声明共签者，但分发包含有共签成员');
851	    }
852	  }
853	
854	  // 4) 签名必须是合法 Base64 且长度符合 Ed25519（64 字节）—— 否则 PROOF_INVALID。
855	  if (!bundleMode) {
856	    sigText = await readFileUtf8(sigAbs);
857	  }
858	  const sigB64 = sigText.replace(/\s+/g, '');
859	  let sigBuf;
860	  if (!/^[A-Za-z0-9+/]*={0,2}$/.test(sigB64) || sigB64.length === 0) {
861	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件不是合法的 Base64 内容');
862	  }
863	  try {
864	    sigBuf = Buffer.from(sigB64, 'base64');
865	  } catch {
866	    throw new ProvError(ERROR_CODES.PROOF_INVALID, '签名文件无法解码为字节');
867	  }
868	  if (sigBuf.length !== 64) {
869	    throw new ProvError(
870	      ERROR_CODES.PROOF_INVALID,
871	      `签名长度非法（Ed25519 应为 64 字节，实际 ${sigBuf.length} 字节）`,
872	    );
873	  }
874	
875	  // 5) 重算证明的规范字节并验签。
876	  //    以磁盘上的 proof.json 原样为真，重新序列化其解析结果用于验签；
877	  //    generate 写出的即为稳定规范形式，因此往返一致。
878	  //
879	  //    错误归类（三者互不相同）：
880	  //      - 提供的公钥与证明中记录的签钥指纹不一致  -> KEY_NOT_FOUND（错误公钥）
881	  //      - 公钥一致但签名验证失败                  -> SIGNATURE_INVALID（签名内容不匹配）
882	  //      - 签名文件本身格式非法（前面）            -> PROOF_INVALID
883	  const providedFingerprint = keyFingerprint(publicKey);
884	  if (providedFingerprint.toLowerCase() !== proof.signerKeyFingerprint.toLowerCase()) {
885	    throw new ProvError(
886	      ERROR_CODES.KEY_NOT_FOUND,
887	      '提供的公钥与证明记录的签名密钥不一致（可能使用了错误公钥）',
888	      {
889	        providedKeyFingerprint: providedFingerprint,
890	        proofKeyFingerprint: proof.signerKeyFingerprint,
891	      },
892	    );
893	  }
894	
895	  const canonicalProof = stableJsonStringify(proof);
896	  let sigOk = false;
897	  try {
898	    sigOk = cryptoVerify(null, Buffer.from(canonicalProof, 'utf8'), publicKey, sigBuf);
899	  } catch {
900	    sigOk = false;
901	  }
902	  if (!sigOk) {
903	    throw new ProvError(
904	      ERROR_CODES.SIGNATURE_INVALID,
905	      '签名与证明内容不匹配（证明可能被改动，或签名已损坏）',
906	    );
907	  }
908	
909	  // 6) 签名通过后重新扫描产物并逐项比对 —— 任何差异均为 INTEGRITY_MISMATCH。
910	  //    排除输出目录：证明/签名/清单（或分发包）通常与产物相邻，验证时不得把它们计入产物。
911	  const excludeDir = inferExcludeDir(bundleMode ? bundleAbs : proofAbs, artifactAbs);
912	  const currentSbom = await buildSbom(artifactAbs, excludeDir);
913	  const currentDigest = computeArtifactDigest(currentSbom);
914	
915	  const mismatches = diffManifest(proof, currentSbom, currentDigest);
916	  if (mismatches.length > 0) {
917	    throw new ProvError(
918	      ERROR_CODES.INTEGRITY_MISMATCH,
919	      `检测到 ${mismatches.length} 处完整性差异`,
920	      { mismatches },
921	    );
922	  }
